/* Interview flow, events and reevaluation domain — extracted from app.js (ADR-0002 domain split).
 * Loaded after shared.js; infra, state and core helpers resolve through window. */
const {state,materialDrafts,api,esc,fmt,toast,modal,modalWide,closeModal,$}=window;
window.flowTab=flowTab;

async function flowTab(el,p){let candidates=[];try{candidates=(await api(`/api/v1/projects/${state.projectId}/candidate-search?q=${encodeURIComponent(state.flowQuery)}&limit=20`)).candidates||[]}catch{};let cid=state.candidateId;if(cid&&!candidates.some(x=>x.candidate_id===cid)){try{const x=await api(`/api/v1/candidates/${cid}/summary`);candidates.unshift(x)}catch{cid=null}}if(!cid)cid=candidates[0]?.candidate_id;if(cid)state.candidateId=cid;if(!cid){el.innerHTML=`<div class="searchbar"><input id="flow-q" class="input" placeholder="搜索候选人"><button class="btn" onclick="flowSearchCandidates()">搜索</button></div><div class="empty"><strong>暂无匹配候选人</strong>通过姓名搜索候选人，而不是固定加载前 100/200 人。</div>`;return}const [ev,re,pipe]=await Promise.all([api(`/api/v1/candidates/${cid}/events`),api(`/api/v1/candidates/${cid}/reevaluations`),api(`/api/v1/candidates/${cid}/pipeline`)]);el.innerHTML=`<div class="panel-head" style="padding:0 0 12px;border:0"><div><h3>招聘流程 · ${stageLabel(pipe.current_stage)}</h3><div class="searchbar"><input id="flow-q" class="input" value="${esc(state.flowQuery)}" placeholder="搜索候选人"><button class="btn small" onclick="flowSearchCandidates()">搜索</button><select class="select" onchange="selectFlowCandidate(this)">${candidates.map(x=>`<option value="${x.candidate_id}" ${x.candidate_id===cid?'selected':''}>${esc(x.display_name)} · ${stageLabel(x.pipeline_stage)}</option>`).join('')}</select></div></div><div class="actions"><button class="btn" onclick="openContactWorkbench()">联系工作台</button><button class="btn" onclick="openPhoneScript('${cid}')">电话脚本</button><button class="btn" onclick="openEvent('${cid}','phone_screen')">＋ 电话筛选</button><button class="btn primary" onclick="openEvent('${cid}','interview')">＋ 面试排期</button><button class="btn" onclick="openReeval('${cid}')">＋ 复评草案</button></div></div><div class="two"><section><h3>面试 / 电话排期</h3>${ev.events.length?`<div class="timeline">${ev.events.map(x=>`<div class="timeline-item"><strong>${esc(x.title||x.event_type)} <span class="status ${statusClass(x.event_state)}">${esc(x.event_state)}</span></strong><small>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():new Date(x.created_at).toLocaleString()} · ${x.duration_minutes||0} 分钟 · ${esc(x.interviewer||'未指定')}</small><div>${esc(x.notes)}</div><div class="subtle">地点：${esc(x.location||'—')} · outcome：${esc(x.outcome||'—')}</div>${x.event_type==='interview'?`<div class="actions" style="margin-top:6px"><button class="btn small" onclick="openScorecards('${x.event_id}')">独立 Scorecard</button></div>`:''}${x.editable_evidence_source?`<div class="actions" style="margin-top:6px"><button class="btn small" onclick="correctEvent('${cid}','${x.event_id}')">更正证据记录</button></div>`:''}${x.event_state==='scheduled'?`<div class="actions" style="margin-top:6px"><button class="btn small primary" onclick="completeEvent('${x.event_id}')">完成并提交结构化反馈</button><button class="btn small" onclick="cancelEvent('${x.event_id}')">取消</button></div>`:''}</div>`).join('')}</div>`:'<div class="empty">暂无电话/面试记录</div>'}</section><section><h3>复评草案</h3>${re.drafts.length?re.drafts.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.summary||'复评草案')}</div><div class="quick-note">${esc(x.state)} · ${new Date(x.created_at).toLocaleString()}</div></div>${x.state==='draft'?`<button class="btn small" onclick="applyReeval('${x.draft_id}')">查看/应用差异</button>`:''}</div>`).join(''):'<div class="empty">暂无复评草案</div>'}</section></div>`}
window.flowSearchCandidates=()=>{state.flowQuery=$('#flow-q')?.value||'';state.candidateId=null;projectWorkspace()};
window.openEvent=(cid,type)=>modal(type==='phone_screen'?'新增电话筛选 / 排期':'新增结构化面试',`<div class="form-grid"><div class="field"><label>标题</label><input id="e-title" class="input" value="${type==='phone_screen'?'电话筛选':'面试'}"></div><div class="field"><label>状态</label><select id="e-state" class="select"><option value="scheduled">已排期</option><option value="completed">已完成</option></select></div><div class="field"><label>计划时间</label><input id="e-time" class="input" type="datetime-local"></div><div class="field"><label>时长（分钟）</label><input id="e-duration" class="input" type="number" value="${type==='phone_screen'?30:60}"></div><div class="field"><label>面试官</label><input id="e-interviewer" class="input"></div><div class="field"><label>地点 / 会议链接</label><input id="e-location" class="input"></div><div class="field full"><label>结构化问题（每行：criterion_key | 问题 | 提问目的）</label><textarea id="e-questions" class="textarea" placeholder="experience | 请说明最近一次招聘项目 | 核实招聘经验"></textarea></div><div class="field full"><label>补充记录</label><textarea id="e-notes" class="textarea"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveEvent('${cid}','${type}')">保存</button>`);
function parseInterviewQuestions(v){return String(v||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{const a=line.split('|').map(x=>x.trim());return {criterion_key:a[0]||'',question:a[1]||a[0]||'',purpose:a[2]||''}})}
window.saveEvent=async(cid,type)=>{try{const time=$('#e-time').value;await api(`/api/v1/candidates/${cid}/events`,{method:'POST',body:JSON.stringify({event_type:type,title:$('#e-title').value,notes:$('#e-notes').value,scheduled_at:time?new Date(time).toISOString():'',duration_minutes:Number($('#e-duration').value||0),interviewer:$('#e-interviewer').value,location:$('#e-location').value,event_state:$('#e-state').value,metadata:{questions:parseInterviewQuestions($('#e-questions').value)}})});toast('流程记录已保存');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};
window.completeEvent=id=>modal('完成面试 / 电话筛选',`<div class="field"><label>Outcome</label><select id="event-outcome" class="select"><option value="proceed">建议推进</option><option value="hold">暂缓</option><option value="reject">建议拒绝</option><option value="completed">已完成</option></select></div><div class="field" style="margin-top:10px"><label>逐标准反馈（每行：criterion_key | rating | observation | supporting_evidence | counter_evidence | recommendation）</label><textarea id="event-feedback" class="textarea" placeholder="experience | strong | 说明了完整项目 | 招聘20人 | 无 | 进入下一轮"></textarea></div><div class="field" style="margin-top:10px"><label>总体建议</label><input id="event-overall" class="input" placeholder="advance / hold / reject"></div><div class="field" style="margin-top:10px"><label>记录</label><textarea id="event-notes" class="textarea"></textarea></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveEventCompletion('${id}')">完成</button>`);
function parseInterviewFeedback(v){return String(v||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{const a=line.split('|').map(x=>x.trim());return {criterion_key:a[0]||'',rating:a[1]||'unknown',observation:a[2]||'',supporting_evidence:a[3]||'',counter_evidence:a[4]||'',recommendation:a[5]||''}})}
window.saveEventCompletion=async id=>{try{const before=await api(`/api/v1/events/${id}`,{method:'PATCH',body:JSON.stringify({event_state:'completed',outcome:$('#event-outcome').value,notes:$('#event-notes').value,metadata:{feedback:parseInterviewFeedback($('#event-feedback').value),overall_recommendation:$('#event-overall').value}})});toast(before.source_id?'已完成并发布结构化面试 Source':'面试已完成');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};window.cancelEvent=async id=>{if(!confirm('取消该排期？'))return;try{await api(`/api/v1/events/${id}`,{method:'PATCH',body:JSON.stringify({event_state:'cancelled'})});toast('排期已取消');await projectWorkspace()}catch(e){toast(e.message,true)}};
window.openReeval=cid=>modal('创建复评草案',`<div class="field"><label>复评摘要</label><textarea id="r-summary" class="textarea"></textarea></div><div class="field" style="margin-top:10px"><label>提议说明（不会直接改人工决定）</label><textarea id="r-proposal" class="textarea"></textarea></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveReeval('${cid}')">创建草案</button>`);
window.saveReeval=async cid=>{try{await api(`/api/v1/candidates/${cid}/reevaluations`,{method:'POST',body:JSON.stringify({summary:$('#r-summary').value,proposal:{note:$('#r-proposal').value}})});toast('复评草案已创建');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};window.applyReeval=async id=>{try{await api(`/api/v1/reevaluations/${id}/apply`,{method:'POST'});toast('草案已标记应用；人工决定未被修改');await projectWorkspace()}catch(e){toast(e.message,true)}};

// P0 #41 (rebased from PR #58): explicit correction of completed structured
// interview evidence. The correction writes a NEW Source revision; the old
// Source and material revision are preserved as history.
window.correctEvent=async(cid,id)=>{try{const data=await api(`/api/v1/candidates/${cid}/events`);const e=(data.events||[]).find(x=>x.event_id===id);if(!e||!e.editable_evidence_source){toast('此记录没有可更正的事件原生证据',true);return}window.correctionEventData=e;const fields=(e.metadata?.questions||[]).map((q,i)=>`<div class="field"><label>问题 ${i+1} · ${esc(q.question||'')}</label><textarea class="textarea" data-corr-answer="${i}">${esc(q.answer||'')}</textarea></div>`).join('');modal('更正已完成面试证据',`<p class="subtle">更正只修改记录备注及已有问题的回答。旧 Source 和材料版本保留历史；已有人工决定需重新核实。</p><div class="field"><label>更正记录备注</label><textarea class="textarea" id="corr-notes">${esc(e.notes||'')}</textarea></div>${fields}`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveEventCorrection('${cid}','${id}','${e.source_id}')">保存更正并发布新证据</button>`)}catch(e){toast(e.message,true)}};
window.saveEventCorrection=async(cid,id,previousSourceId)=>{try{const e=window.correctionEventData;if(!e||e.event_id!==id||e.source_id!==previousSourceId||!e.editable_evidence_source)throw Error('更正上下文已经失效');const metadata=e.metadata||{};const questions=(metadata.questions||[]).map((q,i)=>{const field=document.querySelector(`[data-corr-answer="${i}"]`);if(!field)throw Error('问题编辑器缺失');return{...q,answer:field.value}});const updated=await api(`/api/v1/events/${id}`,{method:'PATCH',body:JSON.stringify({notes:document.querySelector('#corr-notes').value,metadata:{...metadata,questions}})});window.correctionEventData=null;toast(updated.source_id===previousSourceId?'本次内容没有实质变更':'已保存更正；原证据与旧决定保留历史');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};
